import json,pathlib,sqlite3
def accept_events(db_path,events):
    path=pathlib.Path(db_path)
    if path.is_symlink() or not path.is_file():raise ValueError('existing real inbox required')
    if not isinstance(events,list) or not 1<=len(events)<=100:raise ValueError('finite nonempty batch required')
    encoded=[]
    for event in events:
        if not isinstance(event,dict) or any(not isinstance(event.get(k),str) or not event[k] for k in ('topic','id')):raise ValueError('topic and event id required')
        try:payload=json.dumps(event,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False)
        except (ValueError,TypeError) as error:raise ValueError('finite JSON event required') from error
        if len(payload.encode())>65536:raise ValueError('local event budget exceeded')
        encoded.append((event['topic'],event['id'],payload))
    with sqlite3.connect(path,timeout=1) as db:
        db.execute('BEGIN IMMEDIATE')
        inserted=0
        for topic,ident,payload in encoded:
            old=db.execute('SELECT payload FROM inbox WHERE topic=? AND event_id=?',(topic,ident)).fetchone()
            if old is not None:
                if old[0]!=payload:raise ValueError('same event identity changed payload')
                continue
            db.execute("INSERT INTO inbox(topic,event_id,payload,state) VALUES(?,?,?,'pending')",(topic,ident,payload))
            inserted+=1
        return {'received':len(events),'inserted':inserted}
```

原题知识说明：
事件可能重投，处理端需按事件或业务ID幂等，快速接收后可靠排队避免超时。配置失败投递与死信观察，2xx只应在满足接收合同后返回，不能先成功再丢到内存队列。

